package com.renthouse.tenant;
import com.renthouse.auth.*;import com.renthouse.common.api.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/v1/tenant")public class TenantController{private final JdbcTemplate j;public TenantController(JdbcTemplate j){this.j=j;}@GetMapping("/home")public ApiResponse<Home>home(){return ApiResponse.ok(new Home(specials(),stats()));}@GetMapping("/profile")public ApiResponse<Profile>profile(){CurrentUser.requireRole(UserRole.TENANT);long id=CurrentUser.require().id();var p=j.query("SELECT nickname,avatar_url,mobile FROM sys_user WHERE id=?",r->r.next()?new Profile(r.getString(1),r.getString(2),r.getString(3),count("tenant_favorite",id),count("tenant_browse_history",id),count("bill",id),count("repair_ticket",id),count("tenancy_contract",id)):null,id);return ApiResponse.ok(p);}
 private List<Special>specials(){return j.query("SELECT id,title,rent_cent FROM house_listing WHERE publish_status='PUBLISHED' AND is_special=1 ORDER BY special_sort LIMIT 10",(r,n)->new Special(""+r.getLong(1),r.getString(2),r.getInt(3)));}private long count(String table,long id){String col=table.equals("bill")||table.equals("repair_ticket")||table.equals("tenancy_contract")?"tenant_id":"tenant_id";Long c=j.queryForObject("SELECT COUNT(*) FROM "+table+" WHERE "+col+"=?",Long.class,id);return c==null?0:c;}private Map<String,Long>stats(){Map<String,Long>m=new LinkedHashMap<>();m.put("published",one("SELECT COUNT(*) FROM house_listing WHERE publish_status='PUBLISHED'"));m.put("vacant",one("SELECT COUNT(*) FROM property_unit WHERE occupancy_status='VACANT'"));return m;}private long one(String sql){Long v=j.queryForObject(sql,Long.class);return v==null?0:v;}public record Special(String id,String title,int rentCent){}public record Home(List<Special>specials,Map<String,Long>stats){}public record Profile(String nickname,String avatarUrl,String mobile,long favorites,long histories,long bills,long repairs,long contracts){}}
